// Normaliza el body del formulario de contacto.
const b = $input.first().json.body || $input.first().json || {};
const nombre = (b.nombre || '').toString().trim();
const email = (b.email || '').toString().trim();
const empresa = (b.empresa || '').toString().trim() || '—';
const telefono = (b.telefono || '').toString().trim() || '—';
const tipo = (b.tipo || 'Consulta').toString().trim();
const mensaje = (b.mensaje || '').toString().trim();

return [{ json: { nombre, email, empresa, telefono, tipo, mensaje } }];
